# Auto-generated by refactor: extracted verbatim from starter.py (factory + blueprints split).
import logging
from datetime import datetime
from flask_login import UserMixin
from werkzeug.security import check_password_hash, generate_password_hash

from app.extensions import db, login_manager
from app.timeutil import app_today

_logger = logging.getLogger(__name__)


@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))


class User(UserMixin, db.Model):
    id            = db.Column(db.Integer, primary_key=True)
    username      = db.Column(db.String(80), unique=True, nullable=False)
    email         = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(200), nullable=False)
    created_at    = db.Column(db.DateTime, default=datetime.utcnow)
    
    # Profil bilgileri
    weight           = db.Column(db.Float)
    height           = db.Column(db.Float)
    age              = db.Column(db.Integer)
    gender           = db.Column(db.String(10))
    goal             = db.Column(db.String(50))
    fitness_level    = db.Column(db.String(20))
    current_activity = db.Column(db.String(20))
    profile_complete = db.Column(db.Boolean, default=False)

    profile_picture  = db.Column(db.Text, nullable=True)
    # S3'e taşınan avatarın nesne anahtarı. Doluysa avatar S3'ten (pre-signed URL)
    # gösterilir ve profile_picture (base64) temizlenir — böylece ~245 KB base64
    # her HTML yanıtına gömülmez. Boşsa eski base64 davranışına düşülür.
    profile_picture_key = db.Column(db.String(300), nullable=True)
    full_name        = db.Column(db.String(150), nullable=True)
    target_weight    = db.Column(db.Float, nullable=True)
    goal_type        = db.Column(db.String(10), nullable=True)
    streak_count     = db.Column(db.Integer, default=0, server_default='0')
    rank_points      = db.Column(db.Integer, default=0, server_default='0')
    weekly_xp        = db.Column(db.Integer, default=0, server_default='0')
    last_reward_week = db.Column(db.String(10), nullable=True)  # ISO week of last seen reward popup, e.g. "2026-W22"
    last_login       = db.Column(db.Date, nullable=True)

    # Amazon Cognito (e-posta ile giriş) kimlik bağı. Cognito 'sub' claim'i —
    # e-posta değişse bile aynı yerel hesaba sabit kalır. Yalnızca Cognito ile
    # giren kullanıcılarda doludur; klasik kullanıcı adı/şifre hesaplarında NULL.
    cognito_sub      = db.Column(db.String(64), unique=True, nullable=True)

    # Davet/referral döngüsü: her kullanıcının paylaşılabilir tek davet kodu olur;
    # referred_by_id, bu kullanıcıyı getiren davetçiyi işaret eder (çift taraflı ödül).
    referral_code    = db.Column(db.String(16), unique=True, nullable=True)
    # Davetçi silinirse davet edilen kullanıcı SİLİNMEMELİ — bağ kopar (SET NULL).
    referred_by_id   = db.Column(db.Integer, db.ForeignKey("user.id", ondelete="SET NULL"), nullable=True)

    # Para kazanma: freemium hattı. is_premium şu an yalnızca instrümantasyon için
    # tutulur (billing yok); GET /premium upgrade-intent GA olayı ile takip edilir.
    is_premium       = db.Column(db.Boolean, default=False, server_default='false')
    premium_since    = db.Column(db.DateTime, nullable=True)

    referrer = db.relationship("User", remote_side=[id], backref="referrals")

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

    @property
    def avatar_src(self):
        """Gösterim için avatar kaynağı. S3 anahtarı varsa kısa ömürlü pre-signed
        URL üret; yoksa eski base64 data-URL'i (veya None) döndür. Hata/kapalı S3'te
        anahtar varsa None döner → şablon baş harf rozetine düşer. Asla istisna atmaz
        (liste sayfaları çok sayıda avatar render eder)."""
        if self.profile_picture_key:
            import s3_helper
            if s3_helper.is_enabled():
                url = s3_helper.generate_presigned_url(self.profile_picture_key, expires_in=21600)
                if url:
                    return url
            # Anahtar var ama URL üretilemedi (S3 kapalı/erişilemiyor): sessizce
            # baş-harf rozetine düşmeden önce logla ki kesinti tespit edilebilsin (3.6).
            # Modül-seviyesi logger: app-context'siz çağrılarda da güvenli (bu property
            # asla istisna atmamalı — liste sayfaları çok sayıda avatar render eder).
            _logger.warning(
                "[S3] Avatar pre-signed URL üretilemedi (key=%s, enabled=%s) — rozete düşülüyor",
                self.profile_picture_key, s3_helper.is_enabled())
            return None
        return self.profile_picture

    def __repr__(self):
        return f"<User {self.username}>"


